<?php
/**
 * System Settings API — 100% Functional
 * Handles: logo upload/remove, color scheme, layout, accessibility, preferences, audit logs, export, restore
 */

header('Content-Type: application/json');
require_once __DIR__ . '/../lib.php';
require_once __DIR__ . '/../../public/db_connect.php';

require_login();
$me  = current_user();
$role = function_exists('role_key') ? role_key($me['role'] ?? '') : strtolower(trim($me['role'] ?? ''));

if (!in_array($role, ['superadmin', 'developer'])) {  http_response_code(403);  echo json_encode(['success' => false, 'message' => 'Unauthorized access']);  exit;
}

// Parse action + station_id from GET, POST, or JSON body
$raw_input  = file_get_contents('php://input');
$json_input = json_decode($raw_input, true) ?? [];

$action  = $_GET['action']  ?? $_POST['action']  ?? $json_input['action']  ?? '';
$station_id = intval($_GET['station_id'] ?? $_POST['station_id'] ?? $json_input['station_id'] ?? 0);

// Helper: upsert a single setting
function upsertSetting(PDO $pdo, string $key, string $value, int $station_id, int $updated_by): void {  $stmt = $pdo->prepare("  INSERT INTO system_settings (setting_key, setting_value, station_id, updated_by, updated_at)  VALUES (?, ?, ?, ?, NOW())  ON DUPLICATE KEY UPDATE  setting_value = VALUES(setting_value),  updated_by  = VALUES(updated_by),  updated_at  = NOW()  ");  $stmt->execute([$key, $value, $station_id, $updated_by]);
}

try {  switch ($action) {  /* ═══════════════════════════════════════════════════════════════════  UPLOAD LOGO  ═══════════════════════════════════════════════════════════════════ */  case 'upload_logo':  if (!isset($_FILES['logo'])) {  throw new Exception('No logo file uploaded');  }  $file  = $_FILES['logo'];  $allowed = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'];  if (!in_array($file['type'], $allowed)) {  throw new Exception('Invalid file type. Only JPG, PNG, GIF, WebP allowed');  }  if ($file['size'] > 2 * 1024 * 1024) {  throw new Exception('File size exceeds 2MB limit');  }  $upload_dir = __DIR__ . '/../../uploads/logos/';  if (!is_dir($upload_dir)) mkdir($upload_dir, 0755, true);  $ext  = strtolower(pathinfo($file['name'], PATHINFO_EXTENSION));  $filename = 'logo_' . ($station_id > 0 ? "station_{$station_id}_" : 'global_') . time() . '.' . $ext;  $filepath = $upload_dir . $filename;  if (!move_uploaded_file($file['tmp_name'], $filepath)) {  throw new Exception('Failed to save uploaded file');  }  // Store path relative to /public/ so header.php can use it directly  $relative_path = '../uploads/logos/' . $filename;  $setting_key  = $station_id > 0 ? "station_{$station_id}_logo" : 'global_logo';  upsertSetting($pdo, $setting_key, $relative_path, $station_id, $me['id']);  echo json_encode(['success' => true, 'message' => 'Logo uploaded successfully', 'logo_url' => $relative_path]);  break;  /* ═══════════════════════════════════════════════════════════════════  REMOVE LOGO  ═══════════════════════════════════════════════════════════════════ */  case 'remove_logo':  $setting_key = $station_id > 0 ? "station_{$station_id}_logo" : 'global_logo';  $stmt = $pdo->prepare("SELECT setting_value FROM system_settings WHERE setting_key = ? AND station_id = ?");  $stmt->execute([$setting_key, $station_id]);  $current = $stmt->fetchColumn();  if ($current) {  // Path stored as '../uploads/logos/xxx.png' (relative to /public/)  // Convert to absolute: project_root/uploads/logos/xxx.png  $abs_path = __DIR__ . '/../../uploads/logos/' . basename($current);  if (file_exists($abs_path)) unlink($abs_path);  }  $stmt = $pdo->prepare("DELETE FROM system_settings WHERE setting_key = ? AND station_id = ?");  $stmt->execute([$setting_key, $station_id]);  echo json_encode(['success' => true, 'message' => 'Logo removed successfully']);  break;  /* ═══════════════════════════════════════════════════════════════════  SAVE COLOR SCHEME  ═══════════════════════════════════════════════════════════════════ */  case 'save_colors':  $colors = $json_input['colors'] ?? [];  if (empty($colors)) throw new Exception('No color data provided');  $prefix = $station_id > 0 ? "station_{$station_id}_" : 'global_';  foreach ($colors as $key => $value) {  // Sanitize: only accept valid hex colours  $value = preg_match('/^#[0-9A-Fa-f]{6}$/', $value) ? $value : '#002F6C';  upsertSetting($pdo, $prefix . 'color_' . $key, $value, $station_id, $me['id']);  }  echo json_encode(['success' => true, 'message' => 'Color scheme saved successfully']);  break;  /* ═══════════════════════════════════════════════════════════════════  SAVE LAYOUT SETTINGS  ═══════════════════════════════════════════════════════════════════ */  case 'save_layout':  $settings = $json_input['settings'] ?? [];  if (empty($settings)) throw new Exception('No layout data provided');  $prefix = $station_id > 0 ? "station_{$station_id}_" : 'global_';  foreach ($settings as $key => $value) {  upsertSetting($pdo, $prefix . 'layout_' . $key, (string)$value, $station_id, $me['id']);  }  echo json_encode(['success' => true, 'message' => 'Layout settings saved successfully']);  break;  /* ═══════════════════════════════════════════════════════════════════  SAVE ACCESSIBILITY SETTINGS  ═══════════════════════════════════════════════════════════════════ */  case 'save_accessibility':  $settings = $json_input['settings'] ?? [];  if (empty($settings)) throw new Exception('No accessibility data provided');  $prefix = $station_id > 0 ? "station_{$station_id}_" : 'global_';  foreach ($settings as $key => $value) {  $val = is_bool($value) ? ($value ? '1' : '0') : (string)$value;  upsertSetting($pdo, $prefix . 'accessibility_' . $key, $val, $station_id, $me['id']);  }  // Also save font_scale and high_contrast with bare keys (what header.php reads)  if (isset($settings['font_scale'])) {  upsertSetting($pdo, $prefix . 'font_scale', (string)$settings['font_scale'], $station_id, $me['id']);  }  if (isset($settings['high_contrast'])) {  $val = ($settings['high_contrast'] === true || $settings['high_contrast'] === '1') ? '1' : '0';  upsertSetting($pdo, $prefix . 'high_contrast', $val, $station_id, $me['id']);  }  echo json_encode(['success' => true, 'message' => 'Accessibility settings saved successfully']);  break;  /* ═══════════════════════════════════════════════════════════════════  SAVE SYSTEM PREFERENCES  ═══════════════════════════════════════════════════════════════════ */  case 'save_preferences':  $preferences = $json_input['preferences'] ?? [];  if (empty($preferences)) throw new Exception('No preferences data provided');  $prefix = $station_id > 0 ? "station_{$station_id}_" : 'global_';  foreach ($preferences as $key => $value) {  $val = is_bool($value) ? ($value ? '1' : '0') : (string)$value;  upsertSetting($pdo, $prefix . 'pref_' . $key, $val, $station_id, $me['id']);  }  echo json_encode(['success' => true, 'message' => 'System preferences saved successfully']);  break;  /* ═══════════════════════════════════════════════════════════════════  GET ALL SETTINGS  ═══════════════════════════════════════════════════════════════════ */  case 'get_settings':  // Fetch global first, then overlay with station-specific if applicable  $all_rows = [];  $stmt0 = $pdo->prepare("SELECT setting_key, setting_value FROM system_settings WHERE station_id = 0");  $stmt0->execute();  foreach ($stmt0->fetchAll(PDO::FETCH_ASSOC) as $r) {  $all_rows[$r['setting_key']] = $r['setting_value'];  }  if ($station_id > 0) {  $stmtS = $pdo->prepare("SELECT setting_key, setting_value FROM system_settings WHERE station_id = ?");  $stmtS->execute([$station_id]);  foreach ($stmtS->fetchAll(PDO::FETCH_ASSOC) as $r) {  if ($r['setting_value'] !== null && $r['setting_value'] !== '') {  $all_rows[$r['setting_key']] = $r['setting_value'];  }  }  }  $prefix  = $station_id > 0 ? "station_{$station_id}_" : 'global_';  $settings = ['colors' => [], 'layout' => [], 'accessibility' => [], 'preferences' => [], 'logo_url' => null];  foreach ($all_rows as $raw_key => $value) {  // Strip either the global_ or station_X_ prefix  $key = preg_replace('/^(global_|station_\d+_)/', '', $raw_key);  if (strpos($key, 'color_') === 0) {  $settings['colors'][substr($key, 6)] = $value;  } elseif (strpos($key, 'layout_') === 0) {  $settings['layout'][substr($key, 7)] = $value;  } elseif (strpos($key, 'accessibility_') === 0) {  $settings['accessibility'][substr($key, 14)] = $value;  } elseif (strpos($key, 'pref_') === 0) {  $settings['preferences'][substr($key, 5)] = $value;  } elseif ($key === 'logo') {  $settings['logo_url'] = $value;  }  // also pick up bare keys (font_scale, high_contrast) into accessibility  elseif (in_array($key, ['font_scale', 'high_contrast'])) {  $settings['accessibility'][$key] = $value;  }  }  echo json_encode(['success' => true, 'settings' => $settings]);  break;  /* ═══════════════════════════════════════════════════════════════════  GET AUDIT LOGS  ═══════════════════════════════════════════════════════════════════ */  case 'get_audit_logs':  $limit = min(intval($_GET['limit'] ?? 20), 100);  if ($station_id > 0) {  $stmt = $pdo->prepare("  SELECT ss.updated_at AS timestamp, u.username AS user,  ss.category, ss.setting_key AS setting,  '' AS old_value, ss.setting_value AS new_value  FROM system_settings ss  LEFT JOIN users u ON ss.updated_by = u.id  WHERE ss.station_id = ?  ORDER BY ss.updated_at DESC  LIMIT ?  ");  $stmt->execute([$station_id, $limit]);  } else {  $stmt = $pdo->prepare("  SELECT ss.updated_at AS timestamp, u.username AS user,  ss.category, ss.setting_key AS setting,  '' AS old_value, ss.setting_value AS new_value  FROM system_settings ss  LEFT JOIN users u ON ss.updated_by = u.id  ORDER BY ss.updated_at DESC  LIMIT ?  ");  $stmt->execute([$limit]);  }  $logs = $stmt->fetchAll(PDO::FETCH_ASSOC);  foreach ($logs as &$log) {  $log['timestamp'] = date('M d, Y H:i:s', strtotime($log['timestamp']));  $log['category']  = ucfirst($log['category'] ?? 'general');  $log['user']  = $log['user'] ?? 'System';  }  echo json_encode(['success' => true, 'logs' => $logs]);  break;  /* ═══════════════════════════════════════════════════════════════════  EXPORT SETTINGS  ═══════════════════════════════════════════════════════════════════ */  case 'export_settings':  $format = $_GET['format'] ?? 'json';  $stmt = $pdo->prepare("  SELECT setting_key, setting_value, category, updated_at  FROM system_settings WHERE station_id = ?  ORDER BY category, setting_key  ");  $stmt->execute([$station_id]);  $data = $stmt->fetchAll(PDO::FETCH_ASSOC);  $fname = "system_settings_{$station_id}_" . date('Y-m-d');  if ($format === 'json') {  header('Content-Type: application/json');  header("Content-Disposition: attachment; filename=\"{$fname}.json\"");  echo json_encode($data, JSON_PRETTY_PRINT);  } else {  header('Content-Type: text/csv');  header("Content-Disposition: attachment; filename=\"{$fname}.csv\"");  $out = fopen('php://output', 'w');  fputcsv($out, ['Setting Key', 'Value', 'Category', 'Last Updated']);  foreach ($data as $row) {  fputcsv($out, [$row['setting_key'], $row['setting_value'], $row['category'], $row['updated_at']]);  }  fclose($out);  }  exit;  /* ═══════════════════════════════════════════════════════════════════  RESTORE DEFAULTS  ═══════════════════════════════════════════════════════════════════ */  case 'restore_defaults':  if ($station_id > 0) {  $stmt = $pdo->prepare("DELETE FROM system_settings WHERE station_id = ?");  $stmt->execute([$station_id]);  } else {  $pdo->exec("DELETE FROM system_settings WHERE station_id = 0");  $defaults = [  ['global_color_primary',  '#002F6C'],  ['global_color_button',  '#002F6C'],  ['global_color_sidebar',  '#00264D'],  ['global_color_accent',  '#CC0000'],  ['global_color_success',  '#16a34a'],  ['global_color_warning',  '#d97706'],  ['global_color_danger',  '#dc2626'],  ['global_layout_sidebar_style',  'inline'],  ['global_layout_card_arrangement',  'grid'],  ['global_layout_base_font_size',  '14'],  ['global_accessibility_high_contrast',  '0'],  ['global_accessibility_font_scale',  '100'],  ['global_accessibility_focus_indicators', '0'],  ['global_accessibility_reduce_motion',  '0'],  ['global_high_contrast',  '0'],  ['global_font_scale',  '100'],  ['global_pref_language',  'en'],  ['global_pref_timezone',  'Asia/Manila'],  ['global_pref_email_notifications',  '1'],  ['global_pref_sms_notifications',  '0'],  ['global_pref_default_station',  '0'],  ];  $stmt = $pdo->prepare("  INSERT INTO system_settings (setting_key, setting_value, station_id, updated_by, updated_at)  VALUES (?, ?, 0, ?, NOW())  ON DUPLICATE KEY UPDATE setting_value = VALUES(setting_value), updated_at = NOW()  ");  foreach ($defaults as [$k, $v]) {  $stmt->execute([$k, $v, $me['id']]);  }  }  echo json_encode(['success' => true, 'message' => 'Settings restored to defaults successfully']);  break;  default:  throw new Exception("Invalid action: '{$action}'");  }

} catch (Exception $e) {  http_response_code(400);  echo json_encode(['success' => false, 'message' => $e->getMessage()]);
}
